const DB_NAME='toeic-studio-history-v1',PREF='toeic-studio-cloud-history-v1';
export function openArchive(){return new Promise((resolve,reject)=>{const request=indexedDB.open(DB_NAME,1);request.onupgradeneeded=()=>{const db=request.result;db.createObjectStore('attempts',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function archive(action,value){const db=await openArchive();return new Promise((resolve,reject)=>{const tx=db.transaction('attempts',action==='getAll'||action==='get'?'readonly':'readwrite'),store=tx.objectStore('attempts'),request=action==='put'?store.put(value):action==='get'?store.get(value):store.getAll();let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>{db.close();resolve(result)};tx.onerror=()=>{db.close();reject(tx.error)}})}
export function createAccountLearning(ctx){const {bank,esc,icon,heading,toast,sourceLink,snapshot,restore,refresh}=ctx;let identity=null,version=null,backup=null,offset=0,serial=0,restorePending=false;const $=selector=>document.querySelector(selector);const setTitle=id=>bank.sets.find(s=>s.id===id)?.title||({smart:'Buổi ôn cá nhân',review:'Ôn câu sai'})[id]||id;
let enabled=false;try{enabled=localStorage.getItem(PREF)==='yes'}catch{}
const api=async(path,options={})=>{const response=await fetch('/api/'+path,{...options,headers:{'content-type':'application/json',...options.headers}});const data=await response.json();if(!response.ok)throw Object.assign(Error(data.error||'Không kết nối được tài khoản.'),{status:response.status});return data};
async function session(){try{identity=await api('session');version=await (await fetch('./content-version.json')).json();return identity}catch{identity={signedIn:false,storage:false};return identity}}
session();
function page(params){offset=0;restorePending=false;const view=params.get('view')||'account';return `${heading(view==='history'?'Lịch sử làm bài':view==='reports'?'Báo lỗi câu hỏi của tôi':'Tài khoản & bản sao tiến độ','Bản lưu trên thiết bị và bản lưu theo tài khoản được hiển thị riêng.')}<div class="v2-quick"><a href="#account">Tài khoản & sao lưu</a><a href="#account?view=history">Lịch sử & phiên bản</a><a href="#account?view=reports">Báo lỗi đã gửi</a></div><div id="account-panel" data-view="${esc(view)}"><p class="fine-print">Đang mở dữ liệu…</p></div>`}
const signin=()=>'<a class="btn btn-primary" target="_top" href="/signin-with-chatgpt?return_to=%2F%23account">Đăng nhập ChatGPT</a>';
async function afterRender(){if(!$('#account-panel'))return;const token=++serial,view=$('#account-panel').dataset.view;await session();if(token!==serial||!$('#account-panel'))return;try{if(view==='history')await showHistory();else if(view==='reports')await showReports();else{backup=identity.signedIn&&identity.storage?await api('backup'):null;if(token!==serial||!$('#account-panel'))return;drawAccount()}}catch(error){if($('#account-panel'))$('#account-panel').innerHTML=`<div class="learning-note"><strong>Chưa mở được dữ liệu</strong><p>${esc(error.message)}</p><button class="btn btn-secondary" data-account-retry>Thử lại</button></div>`}}
function drawAccount(){const panel=$('#account-panel');if(!panel)return;panel.innerHTML=`<section class="learning-note"><strong>${identity.signedIn?'Đã nhận diện tài khoản ChatGPT':'Đang dùng dữ liệu trên thiết bị'}</strong><p>${identity.signedIn?'Bản sao và lịch sử trên máy chủ chỉ được đọc bằng tài khoản đã tạo chúng.':'Bạn vẫn có thể học và lưu lịch sử trên trình duyệt. Đăng nhập để có bản sao trên tài khoản.'}</p>${identity.signedIn?'':signin()}</section>${identity.signedIn&&identity.storage?`<section class="panel"><h2>Bản sao tiến độ theo tài khoản</h2><p class="fine-print">${backup?.data?'Phiên bản '+backup.revision+' · lưu lúc '+new Date(backup.updatedAt).toLocaleString('vi-VN'):'Tài khoản chưa có bản sao.'} Bản sao gồm tiến độ, ghi chú, lịch ôn và bài làm dở. Đây là sao lưu thủ công; hệ thống báo xung đột nếu thiết bị khác đã lưu bản mới hơn.</p><div class="data-actions"><button class="btn btn-primary" data-cloud-save>Lưu tiến độ hiện tại lên tài khoản</button><button class="btn btn-secondary" data-cloud-refresh>Tải lại thông tin</button>${backup?.data?'<button class="btn btn-secondary" data-cloud-restore>Xem bản sao trước khi khôi phục</button>':''}</div><div id="restore-preview"></div></section><section class="panel section-gap"><h2>Lịch sử làm bài theo tài khoản</h2><p class="fine-print">Khi bật, lượt làm mới được chấm lại trên máy chủ và lưu cùng phiên bản câu hỏi. Các lượt có trên máy vẫn được giữ nếu mất mạng. Nội dung câu hỏi hiện vẫn có thể đọc ở phía trình duyệt; đây chưa phải chế độ thi bảo mật.</p><button class="btn ${enabled?'btn-soft':'btn-primary'}" data-cloud-enable aria-pressed="${enabled}">${enabled?'Đang bật lưu lịch sử theo tài khoản':'Bật lưu lịch sử theo tài khoản'}</button><button class="btn btn-secondary" data-cloud-retry>Gửi lại lượt chưa lưu</button><p id="cloud-sync-status" class="fine-print"></p></section>`:identity.signedIn?'<p class="fine-print">Lưu trữ tài khoản đang được chuẩn bị. Bản học trên trình duyệt vẫn được giữ.</p>':''}<div class="panel section-gap"><h2>Dữ liệu trên trình duyệt</h2><p class="fine-print">Lịch sử mới được lưu trong IndexedDB cùng nguyên văn câu hỏi, đáp án và giải thích lúc làm. Bộ nhớ thiết bị vẫn có thể bị xóa bởi trình duyệt; xuất bản sao để tự giữ dữ liệu.</p><a class="btn btn-secondary" href="#account?view=history">Xem & xuất lịch sử</a><a class="btn btn-secondary" href="#progress">Xuất / nhập tiến độ và ghi chú</a></div>`}
async function recordAttempt(input){try{version||=await (await fetch('./content-version.json')).json();const item={schema:1,id:crypto.randomUUID(),setId:input.set.id,mode:input.mode,date:new Date().toISOString(),bankVersion:bank.contentVersion||version.bankVersion,questions:input.set.questions.map(q=>({...q,version:bank.questionVersions?.[q.id]||version.questionVersions[q.id]})),answers:{...input.answers},score:input.score,verification:'device-graded',cloud:'pending'};await archive('put',JSON.parse(JSON.stringify(item)));if(enabled)void upload(item)}catch(error){toast('Chưa lưu được lịch sử đầy đủ. Hãy xuất tiến độ trước khi đóng trang.')}}
async function upload(item){await session();if(!identity.signedIn||!identity.storage)return false;try{const result=await api('attempts',{method:'POST',body:JSON.stringify({id:item.id,setId:item.setId,mode:item.mode,date:item.date,bankVersion:item.bankVersion,questionIds:item.questions.map(q=>q.id),answers:item.answers})});await archive('put',{...item,cloud:'saved',serverDate:result.date});return true}catch(error){if(error.status===409){item.cloud='version-conflict';await archive('put',item)}return false}}
async function retryUploads(){const items=await archive('getAll');let saved=0,remaining=0;for(const item of items.filter(item=>item.cloud!=='saved')){if(await upload(item))saved++;else remaining++}const status=$('#cloud-sync-status');if(status)status.textContent=`Đã lưu ${saved} lượt; còn ${remaining} lượt trên thiết bị. Lượt dùng nội dung cũ được giữ nguyên, không tự chấm lại.`}
const row=(item,cloud)=>`<article class="v2-word"><div><strong>${esc(setTitle(item.setId))}</strong><span>${item.score?.correct??item.correct}/${item.score?.total??item.total} câu đúng · ${new Date(item.date).toLocaleString('vi-VN')}</span><small>${cloud?'Máy chủ chấm điểm':'Trên thiết bị'} · nội dung ${esc(item.bankVersion.slice(0,12))}${!cloud?' · '+(item.cloud==='saved'?'đã có trên tài khoản':item.cloud==='version-conflict'?'giữ bản cũ trên thiết bị':'chưa lưu lên tài khoản'):''}</small></div><button class="btn btn-soft" data-history-id="${esc(item.id)}" data-history-cloud="${cloud?'yes':'no'}">Xem bài & phiên bản</button></article>`;
async function showHistory(){const items=(await archive('getAll')).sort((a,b)=>b.date.localeCompare(a.date));const remote=identity.signedIn&&identity.storage?await api('attempts?offset='+offset):{items:[],nextOffset:null};if(!$('#account-panel'))return;$('#account-panel').innerHTML=`<div class="learning-note"><strong>Giữ nguyên bài đã làm</strong><p>Lời giải dưới đây lấy từ bản câu hỏi đã lưu trong lượt làm; không thay bằng lời giải hiện tại. Lịch sử này bắt đầu từ bản cập nhật có chức năng lưu phiên bản; các lượt cũ chỉ còn trong tiến độ cũ, không được gán phiên bản suy đoán.</p><button class="btn btn-secondary" data-history-export>Xuất toàn bộ lịch sử trên thiết bị</button></div><h2>Lượt trên thiết bị (${items.length})</h2>${items.length?items.slice(offset,offset+20).map(i=>row(i,false)).join(''):'<p class="fine-print">Chưa có lượt lưu phiên bản trên thiết bị này.</p>'}<h2 class="section-gap">Lượt theo tài khoản</h2>${identity.signedIn?remote.items.map(i=>row(i,true)).join('')||'<p class="fine-print">Chưa có lượt trên tài khoản.</p>':signin()}<div class="data-actions">${offset?'<button class="btn btn-secondary" data-history-prev>Trang trước</button>':''}${items.length>offset+20||remote.nextOffset!==null?'<button class="btn btn-secondary" data-history-next>Trang tiếp</button>':''}</div>`}
async function detail(id,cloud){const item=cloud?await api('attempts/'+encodeURIComponent(id)):await archive('get',id);if(!item||!$('#account-panel'))return;$('#account-panel').innerHTML=`<a class="btn btn-secondary" href="#account?view=history">Về danh sách</a><div class="learning-note section-gap"><strong>${esc(setTitle(item.setId))} · ${item.score.correct}/${item.score.total} câu đúng</strong><p>Phiên bản nội dung ${esc(item.bankVersion)} · ${item.verification==='server-graded'?'được máy chủ chấm':'được trình duyệt chấm khi làm'}</p></div>${item.questions.map((q,i)=>{const result=item.score.results[i];return `<article class="answer-review-card ${result.correct?'is-correct':'is-wrong'}"><small>Câu ${i+1} · phiên bản ${esc(q.version?.slice(0,12)||'không ghi nhận')}</small><h3>${esc(q.prompt)}</h3><p>Bạn trả lời: ${esc(result.answered?q.type==='text'?result.answer:q.options[Number(result.answer)]:'Chưa trả lời')}</p><p>Đáp án lúc làm: <strong>${esc(q.type==='text'?q.accept[0]:q.options[q.answer])}</strong></p><div class="answer-explanation">${esc(q.explanation)}</div>${sourceLink(q.sourceId,q.page)}</article>`}).join('')}`}
async function showReports(){const data=identity.signedIn&&identity.storage?await api('reports'):{items:[]};if(!$('#account-panel'))return;$('#account-panel').innerHTML=`<div class="learning-note"><strong>Báo lỗi được lưu trong hệ thống của website</strong><p>Báo lỗi không tự thay đổi đáp án. Người quản lý cần kiểm tra nội dung trước khi sửa và xuất bản phiên bản mới.</p></div>${identity.signedIn?data.items.map(r=>`<article class="v2-word"><div><strong>${esc(r.question_id)}</strong><span>${esc(r.detail||r.reason)}</span><small>${r.status==='open'?'Đang chờ kiểm tra':esc(r.status)} · ${new Date(r.created_at).toLocaleString('vi-VN')}</small></div></article>`).join('')||'<p class="fine-print">Bạn chưa gửi báo lỗi.</p>':signin()}`}
function reportButton(id){return `<button class="text-button" data-question-report="${esc(id)}">Báo lỗi câu này</button>`}
function report(id){const q=bank.sets.flatMap(s=>s.questions).find(q=>q.id===id);if(!q)return;let dialog=$('#question-report-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='question-report-dialog';dialog.className='settings-dialog';document.body.append(dialog)}dialog.innerHTML=`<form id="question-report-form"><div class="dialog-header"><h2>Báo lỗi câu hỏi</h2><button type="button" class="icon-button" data-report-close aria-label="Đóng">×</button></div><p class="fine-print">${esc(q.prompt)}</p><input type="hidden" name="questionId" value="${esc(id)}"><label class="form-field">Vấn đề<select name="reason"><option value="answer">Đáp án</option><option value="question">Nội dung câu</option><option value="explanation">Giải thích</option><option value="source">Nguồn tài liệu</option><option value="other">Khác</option></select></label><label class="form-field">Mô tả<textarea name="detail" maxlength="1500" class="note-editor" required placeholder="Chỗ nào chưa đúng? Bạn đã đối chiếu trang nào?"></textarea></label><p class="fine-print">Gửi báo lỗi cần đăng nhập; chỉ lưu nội dung bạn nhập và mã câu hỏi.</p><button class="btn btn-primary" type="submit">Gửi vào hệ thống kiểm tra</button><p id="report-status" role="status"></p></form>`;dialog.showModal()}
document.addEventListener('submit',async event=>{if(event.target.id!=='question-report-form')return;event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(form));await api('reports',{method:'POST',body:JSON.stringify({...data,id:crypto.randomUUID()})});$('#report-status').textContent='Đã lưu báo lỗi, đang chờ kiểm tra.';form.querySelector('textarea').disabled=true}catch(error){$('#report-status').textContent=error.message;button.disabled=false}});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
 if(button.hasAttribute('data-question-report'))report(button.dataset.questionReport);
 else if(button.hasAttribute('data-report-close'))$('#question-report-dialog').close();
 else if(button.hasAttribute('data-cloud-save')){button.disabled=true;const data=snapshot(),saved=await api('backup',{method:'PUT',body:JSON.stringify({revision:backup?.revision||0,data})});backup={...saved,data};drawAccount();toast('Đã lưu bản sao tiến độ lên tài khoản.')}
 else if(button.hasAttribute('data-cloud-refresh')||button.hasAttribute('data-account-retry'))afterRender();
 else if(button.hasAttribute('data-cloud-restore')){restorePending=true;$('#restore-preview').innerHTML=`<div class="learning-note"><strong>Khôi phục bản sao ${backup.revision}</strong><p>Bản sao có ${Object.keys(backup.data.completed||{}).length} video hoàn thành và ${Object.keys(backup.data.notes||{}).length} ghi chú. Thao tác sẽ thay tiến độ đang có trên trình duyệt. Xuất bản hiện tại ở trang Tiến độ trước nếu cần.</p><button class="btn btn-primary" data-cloud-confirm>Xác nhận thay dữ liệu trên trình duyệt</button></div>`}
 else if(button.hasAttribute('data-cloud-confirm')&&restorePending&&backup?.data){restorePending=false;restore(backup.data);toast('Đã khôi phục bản sao từ tài khoản.')}
 else if(button.hasAttribute('data-cloud-enable')){enabled=!enabled;try{localStorage.setItem(PREF,enabled?'yes':'no')}catch{}drawAccount();if(enabled)await retryUploads()}
 else if(button.hasAttribute('data-cloud-retry'))await retryUploads();
 else if(button.hasAttribute('data-history-id'))await detail(button.dataset.historyId,button.dataset.historyCloud==='yes');
 else if(button.hasAttribute('data-history-next')){offset+=20;await showHistory()}
 else if(button.hasAttribute('data-history-prev')){offset=Math.max(0,offset-20);await showHistory()}
 else if(button.hasAttribute('data-history-export')){const blob=new Blob([JSON.stringify({app:'TOEIC Studio History',exportedAt:new Date().toISOString(),attempts:await archive('getAll')},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='toeic-studio-lich-su-phien-ban.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
 }catch(error){toast(error.message)}finally{if(button.isConnected)button.disabled=false}});
return {page,afterRender,recordAttempt,reportButton};
}
